run:
() => {
      const G = window.hamsi, m = { seasons: 0, reis: 0, stars: 0, worth: 0, catchKg: 0, sales: 0, boats: '', gameErrors: 0 };
      for (const seed of [20261027, 1, 2]) {
        let a = seed; // mulberry32, same algorithm as the game's arena-kit core.mulberry32
        Math.random = () => { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
        G.api.startNewGame();
        for (let i = 0; i < 600 && G.mode !== 'end'; i++) window.hamsiSim(30); // 1/30 s steps, bot on, until the season ends
        const r = G.result || {};
        m.seasons += G.mode === 'end' ? 1 : 0; m.reis += r.reis ? 1 : 0; m.stars += r.stars || 0; m.worth += Math.round(r.worth || 0);
        m.catchKg += Math.round(G.tot.catch); m.sales += Math.round(G.tot.sales); m.boats += G.boatClass;
      }
      m.gameErrors = G.errors.length;
      window.__gateM = m;
    }
